(() => {
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(r){return `<article class="rw-card"><img class="rw-app" src="/assets/original/40a6e56dd9fe8c72.svg" alt=""><div class="rw-person">${r.avatar?`<img class="rw-avatar" src="${r.avatar}" alt="Avatar de ${esc(r.name)}" loading="lazy">`:`<span class="rw-avatar rw-initial" aria-hidden="true">${esc(r.name.slice(0,1))}</span>`}<div><b>${esc(r.name)}</b><small>${esc(r.username)}</small><div class="rw-stars" aria-label="${r.rating} de 5 estrelas">${'★'.repeat(r.rating)}<span>${'☆'.repeat(5-r.rating)}</span></div></div></div><blockquote class="rw-excerpt">“${esc(r.excerpt)}”</blockquote>${r.summary?`<p class="rw-comment-summary">${esc(r.summary)}</p>`:''}<div class="rw-card-foot"><span><img src="/assets/original/570507b5e2ef9723.svg" alt="">${esc(r.product)}</span><time>${esc(r.date)}</time></div></article>`}
function column(rows,index,variant='rw-desktop'){const cards=rows.map(card).join('');return `<div class="rw-column ${variant}"><div class="rw-track" style="--rw-duration:${[44,52,48,65][index]}s;--rw-direction:${index===1?'reverse':'normal'}"><div class="rw-group">${cards}</div><div class="rw-group" aria-hidden="true">${cards}</div></div></div>`}
function page(){const rows=window.originalReviews||[];if(!rows.length)return '';return `<section class="rw-section"><div class="wrap"><div class="rw-heading"><div><span class="eyebrow">AVALIAÇÕES DA STARBUXX</span><h2>Quem comprou<br><em>conta sua experiência</em></h2><p>Trechos e resumos dos relatos publicados na StarBuxx.</p></div><a class="landing-outline" href="https://star-buxx.com/avaliacoes" target="_blank" rel="noopener noreferrer">Ver avaliações originais ↗</a></div><div class="rw-wall" aria-label="Avaliações da loja original em movimento">${[0,1,2].map(i=>column(rows.filter((r,j)=>j%3===i),i)).join('')}${[0,1].map(i=>column(rows.filter((r,j)=>j%2===i),i,'rw-tablet')).join('')}${column(rows,3,'rw-mobile')}</div></div></section>`}
window.reviewWall={page};
})();
